/* Published presentation only. The economic catalogue and its artwork stay canonical. */
(() => {
 'use strict';
 const defaults={theme:'night',features:{constellations:true,missions:true,journey:true,awakening:true,sanctuary:true,events:true},banner:{enabled:false,title:'Chaque carte crée un lien.',body:'',card_id:'',target:'constellations',starts_at:null,ends_at:null},awakening:{mode:'all',card_ids:[],fragments:false},variants:[]};
 const clone=v=>JSON.parse(JSON.stringify(v)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let config=clone(defaults),busy=false,lastFetch=0,queued=false,bannerSignature='',artSignature='',generation=0;
 const account=()=>window.KizunaAccount?.getSnapshot?.()||{},game=()=>window.KizunaGame?.getSnapshot?.()||{cards:[],owned:[]},progress=()=>window.KizunaAdventure?.getSnapshot?.().state||{};
 const allowed=key=>config.features[key]!==false;
 const eligible=id=>allowed('awakening')&&(config.awakening.mode!=='selected'||config.awakening.card_ids.includes(id));
 function accept(value){if(!value||!['night','aurora','ember'].includes(value.theme)||!value.features||!value.banner||!value.awakening||!Array.isArray(value.awakening.card_ids)||!Array.isArray(value.variants))return;const next=JSON.stringify(value);if(next===JSON.stringify(config))return;generation++;config=clone(value);document.documentElement.dataset.kzTheme=config.theme;window.dispatchEvent(new CustomEvent('kizuna:design-change'));schedule();}
 async function refresh(){const c=window.KIZUNA_CONFIG;if(busy||!c?.supabaseUrl||!c?.supabaseKey)return;const token=generation;busy=true;try{const r=await fetch(c.supabaseUrl+'/rest/v1/kizuna_live_design?select=config&limit=1',{headers:{apikey:c.supabaseKey},credentials:'omit',cache:'no-store'});if(!r.ok)throw Error('Design unavailable');const rows=await r.json();if(token===generation)accept(rows[0]?.config);lastFetch=Date.now();}catch{/* Keep the last known presentation and normal collection access. */}finally{busy=false;}}
 function banner(){const host=document.querySelector('#kzHome>.wrap');if(!host)return;let root=document.getElementById('ksuLiveBanner');if(!root){root=document.createElement('article');root.id='ksuLiveBanner';root.className='ksu-banner';host.prepend(root);root.addEventListener('click',e=>{if(!e.target.closest('[data-ksu-target]'))return;const t=config.banner.target;if(['boosters','collection'].includes(t))window.KizunaGame.showTab(t);else window.KizunaAdventure?.navigate(t);});}
  const b=config.banner,active=b.enabled&&(!b.starts_at||Date.parse(b.starts_at)<=Date.now())&&(!b.ends_at||Date.parse(b.ends_at)>Date.now());root.hidden=!active;if(!active)return;const card=game().cards.find(c=>c.id===b.card_id),sig=JSON.stringify([b,card?.image]);if(sig===bannerSignature)return;bannerSignature=sig;
  root.innerHTML='<div><span class="ksu-kicker">À LA UNE SUR KIZUNA</span><h2>'+esc(b.title)+'</h2><p>'+esc(b.body)+'</p><button class="soft-btn" type="button" data-ksu-target>Découvrir →</button></div>'+(card?'<img src="'+esc(card.image)+'" alt="'+esc(card.name)+'" loading="lazy" referrerpolicy="no-referrer">':'');
 }
 function variantImage(id){const p=progress(),chosen=p.art?.[id];if(!chosen||account().loading)return null;return config.variants.find(v=>v.id===chosen&&v.card_id===id&&(p.awakened?.[id]||0)>=v.level)?.image||null;}
 function decorate(){
  banner();document.querySelectorAll('[data-ka-view]').forEach(b=>b.hidden=!allowed(b.dataset.kaView)&&!(b.dataset.kaView==='sanctuary'&&progress().sanctuary?.public));
  const p=progress(),g=game(),catalogue=new Map(g.cards.map(c=>[c.id,c])),owned=new Set(g.owned.map(c=>c.id));
  document.querySelectorAll('.tcard[data-kz-card-id],#kaAdventureContent [data-ka-select],.ka-awakening-preview>.ka-awakened-art').forEach(node=>{if(node.closest('#revealBackdrop'))return;const id=node.dataset.kzCardId||node.dataset.kaSelect||document.querySelector('#kaAdventureContent [data-ksu-card]')?.dataset.ksuCard;const img=node.querySelector('img');if(!img||!id)return;const base=catalogue.get(id)?.image;if(!base)return;const next=owned.has(id)?variantImage(id)||base:base;if(img.getAttribute('src')!==next)img.src=next;});
  const detail=document.querySelector('.ka-awakening-preview>div:last-child');if(!detail){artSignature='';return;}const id=document.querySelector('.ka-awakening-list button.active')?.dataset.kaSelect;if(!id)return;
  const rows=config.variants.filter(v=>v.card_id===id),sig=JSON.stringify([id,rows,p.art?.[id],p.awakened?.[id],p.fragments,config.awakening,owned.has(id),account().user?.id,account().loading]);let root=document.getElementById('ksuArtChoices');if(root&&sig===artSignature)return;artSignature=sig;if(!root){root=document.createElement('section');root.id='ksuArtChoices';detail.append(root);}root.dataset.ksuCard=id;
  const level=p.awakened?.[id]||0,cost=level===0?2:5,fragmentButton=config.awakening.fragments&&level<2?'<p>'+Number(p.fragments||0)+' fragment(s) d’Éveil · un fragment par nouveau défi réclamé.</p><button type="button" class="soft-btn" data-ksu-fragments="'+esc(id)+'" '+(!account().user||!eligible(id)||Number(p.fragments||0)<cost||!owned.has(id)?'disabled':'')+'>Utiliser '+cost+' fragments pour '+(level?'la Transcendance':'l’Éveil')+'</button>':'';
  root.innerHTML=(!eligible(id)?'<p>Cette carte n’est pas éligible à un nouvel Éveil actuellement. Les niveaux déjà obtenus sont conservés.</p>':'')+fragmentButton+(rows.length?'<h3>Illustrations alternatives</h3><p>Présentation personnelle · rareté et statistiques conservées.</p><div class="ksu-art-options"><button type="button" class="soft-btn" data-ksu-art="" data-ksu-card="'+esc(id)+'" aria-pressed="'+!p.art?.[id]+'" '+(!account().user?'disabled':'')+'>Originale</button>'+rows.map(v=>'<button class="ksu-art" type="button" data-ksu-art="'+esc(v.id)+'" data-ksu-card="'+esc(id)+'" aria-pressed="'+(p.art?.[id]===v.id)+'" '+(!account().user||level<v.level||!owned.has(id)?'disabled':'')+'><img src="'+esc(v.image)+'" alt="" loading="lazy" referrerpolicy="no-referrer"><strong>'+esc(v.label)+'</strong><small>'+(['Standard','Éveil requis','Transcendance requise'][v.level])+'</small></button>').join('')+'</div>':'');
 }
 function schedule(){if(queued)return;queued=true;requestAnimationFrame(()=>{queued=false;decorate();});}
 document.addEventListener('click',async e=>{const b=e.target.closest('[data-ksu-art],[data-ksu-fragments]');if(!b||b.disabled)return;if(b.hasAttribute('data-ksu-fragments')){const p=progress(),id=b.dataset.ksuFragments,level=(p.awakened?.[id]||0)+1,cost=level===1?2:5;if(confirm('Utiliser '+cost+' fragments pour ce niveau ? Aucune carte ni Chakra ne sera consommé.'))await window.KizunaAdventure?.perform('awaken',{id,level,method:'fragments'});}else await window.KizunaAdventure?.perform('equip_art',{id:b.dataset.ksuCard,variant:b.dataset.ksuArt});schedule();});
 new MutationObserver(schedule).observe(document.querySelector('main'),{subtree:true,childList:true});
 for(const name of ['kizuna:game-change','kizuna:adventure-change','kizuna:design-change'])window.addEventListener(name,schedule);document.addEventListener('kizuna:account-change',schedule);
 window.addEventListener('focus',()=>{if(Date.now()-lastFetch>60000)refresh();});window.setInterval(()=>{if(!document.hidden){banner();if(Date.now()-lastFetch>60000)refresh();}},60000);
 window.KizunaStudio=Object.freeze({get:()=>clone(config),defaults:()=>clone(defaults),accept,refresh,allowed,eligible,variantImage});refresh();schedule();
})();
